        uint256 count = 0;

        for (uint256 i = 0; i < _delegatedTransfers.length; i++) {
            if (_delegatedTransfers[i].status == _status) {
                delegatedTransfers[count] = _delegatedTransfers[i];
                count++;
            }
        }

        assembly {
            mstore(delegatedTransfers, count)
        }
    }
}
